  difficulty = excluded.difficulty,
  topic_tags = excluded.topic_tags,
  skill_tags = excluded.skill_tags,
  updated_at = now();

do $$
begin
  if (select count(*) from public.question_difficulty_profiles where quiz_id = 'science-grade1') <> 75 then
    raise exception 'science-grade1 profile count must be exactly 75';
  end if;
  if (select count(*) from public.question_difficulty_profiles where quiz_id = 'science-grade1-boys') <> 75 then
    raise exception 'science-grade1-boys profile count must be exactly 75';
  end if;
end
$$;

commit;

select
  quiz_id,
  count(*) as seeded_questions,
  min(difficulty) as min_difficulty,
  max(difficulty) as max_difficulty
from public.question_difficulty_profiles
where quiz_id in ('science-grade1', 'science-grade1-boys')
group by quiz_id
order by quiz_id;
